[.tooling/components/apis/rag-service/docs/07-api-reference-future.md#python-client-example]

### Python Client Example

```python
import requests
import json

class RAGServiceClient:
    def __init__(self, base_url: str, token: str):
        self.base_url = base_url
        self.headers = {
            "Authorization": f"Bearer {token}",
            "Content-Type": "application/json"
        }

    def search_documents(self, query: str, limit: int = 10):
        """Search documents using the RAG service."""
        url = f"{self.base_url}/api/rag/v1/search"
        payload = {
            "query": query,
            "limit": limit,
            "include_ai_response": True
        }

        response = requests.post(url, headers=self.headers, json=payload)
        response.raise_for_status()
        return response.json()

    def upload_document(self, file_path: str, title: str, metadata: dict = None):
        """Upload a document to the RAG service."""
        url = f"{self.base_url}/api/v1/documents"

        with open(file_path, 'rb') as file:
            files = {'file': file}
            data = {
                'title': title,
                'metadata': json.dumps(metadata or {})
            }

            # Remove Content-Type for multipart upload
            headers = {k: v for k, v in self.headers.items() if k != "Content-Type"}

            response = requests.post(url, headers=headers, files=files, data=data)
            response.raise_for_status()
            return response.json()

# Usage example
client = RAGServiceClient("<base-url>", "<jwt-token>")

# Search documents
results = client.search_documents("What is machine learning?")
print(f"Found {len(results['data']['results'])} results")
print(f"AI Response: {results['data']['ai_response']['answer']}")

# Upload document
result = client.upload_document(
    "research_paper.pdf",
    "Machine Learning Research Paper",
    {"author": "John Doe", "category": "research"}
)
print(f"Document uploaded with ID: {result['data']['id']}")
```

