[.tooling/components/apis/rag-service/docs/07-api-reference-future.md#javascriptnodejs-example]

### JavaScript/Node.js Example

```javascript
class RAGServiceClient {
  constructor(baseUrl, token) {
    this.baseUrl = baseUrl;
    this.headers = {
      Authorization: `Bearer ${token}`,
      'Content-Type': 'application/json',
    };
  }

  async searchDocuments(query, limit = 10) {
    const response = await fetch(`${this.baseUrl}/api/rag/v1/search`, {
      method: 'POST',
      headers: this.headers,
      body: JSON.stringify({
        query,
        limit,
        include_ai_response: true,
      }),
    });

    if (!response.ok) {
      throw new Error(`HTTP error! status: ${response.status}`);
    }

    return await response.json();
  }

  async uploadDocument(file, title, metadata = {}) {
    const formData = new FormData();
    formData.append('file', file);
    formData.append('title', title);
    formData.append('metadata', JSON.stringify(metadata));

    const headers = { ...this.headers };
    delete headers['Content-Type']; // Let browser set boundary

    const response = await fetch(`${this.baseUrl}/api/v1/documents`, {
      method: 'POST',
      headers,
      body: formData,
    });

    if (!response.ok) {
      throw new Error(`HTTP error! status: ${response.status}`);
    }

    return await response.json();
  }
}

// Usage example
const client = new RAGServiceClient('<base-url>', '<jwt-token>');

// Search documents
try {
  const results = await client.searchDocuments('What is artificial intelligence?');
  console.log(`Found ${results.data.results.length} results`);
  console.log(`AI Response: ${results.data.ai_response.answer}`);
} catch (error) {
  console.error('Search failed:', error);
}
```

